def _parse_optional_non_negative_int(value: str | None) -> int | None:
    """Parse an optional integer that must be zero or greater (zero allowed)."""
    raw = (value or "").strip()
    if not raw:
        return None
    parsed = int(raw)
    if parsed < 0:
        raise ValueError("Value must be zero or greater.")
    return parsed


def _parse_required_positive_int(value: str | None) -> int:
    parsed = int((value or "").strip())
    if parsed <= 0:
        raise ValueError("Value must be positive.")
    return parsed


def _parse_bool_choice(value: str | None) -> bool | None:
    if value in {"true", "True", "on", "yes", "1"}:
        return True
    if value in {"false", "False", "no", "0"}:
        return False
    return None


def _parse_optional_date(value: str | None) -> date | None:
    raw = (value or "").strip()
    if not raw:
        return None
    parsed = parse_date(raw)
    if parsed is None:
        raise ValueError("Invalid date format.")
    return parsed


def _parse_local_datetime(value: str | None) -> datetime | None:
    raw = (value or "").strip()
    if not raw:
        return None
    parsed = parse_datetime(raw)
    if parsed is None:
        raise ValueError("Invalid date/time format.")
    if timezone.is_naive(parsed):
        parsed = timezone.make_aware(parsed, timezone.get_current_timezone())
    return parsed


def _charter_intake_data(post: QueryDict) -> dict[str, Any]:
