def _google_place_details_for_charter(
    *,
    calendar: InternalCalendar,
    include_contact: bool,
    include_reviews: bool,
) -> dict[str, Any] | None:
    google_place_id = (calendar.google_place_id or "").strip()
    api_key = getattr(settings, "GOOGLE_PLACES_API_KEY", "") or ""
    if not google_place_id or not api_key or not (include_contact or include_reviews):
        return None

    expand = ["display", "maps"]
    if include_contact:
        expand.append("business")
    if include_reviews:
        expand.append("rating")

    try:
        return GooglePlacesService.get_place_details(
            api_key=api_key,
            place_id=google_place_id,
            expand=expand,
        )
    except GooglePlacesUpstreamError:
        logger.warning(
            "Google Places fallback unavailable for charter calendar %s",
            calendar.id,
        )
        return None


def _charter_public_profile_fallbacks(
    *, calendar: InternalCalendar, is_shadow_page: bool
) -> dict[str, Any]:
    allow_google_contact = is_shadow_page or calendar.use_google_contact_info
    allow_google_reviews = is_shadow_page or calendar.use_google_reviews

    address = (calendar.business_address or "").strip()
    phone = (calendar.business_phone or "").strip()
    website_url = _safe_external_profile_url(calendar.business_website_url)

    needs_google_contact = allow_google_contact and (
        not address or not phone or not website_url
    )
    needs_google_reviews = (
        allow_google_reviews and not calendar.testimonials and not calendar.reviews_url
    )
    google_place = _google_place_details_for_charter(
        calendar=calendar,
        include_contact=needs_google_contact,
        include_reviews=needs_google_reviews,
    )

    contact_uses_google = False
    google_maps_url = ""
    contact_google_maps_url = ""
    if google_place:
        google_maps_url = _safe_external_profile_url(
            google_place.get("google_maps_uri")
        )
        if allow_google_contact:
            contact_google_maps_url = google_maps_url
            if not address:
                address = (google_place.get("formatted_address") or "").strip()
                contact_uses_google = bool(address)
            if not phone:
                phone = (
                    google_place.get("national_phone_number")
                    or google_place.get("international_phone_number")
                    or ""
                ).strip()
                contact_uses_google = contact_uses_google or bool(phone)
            if not website_url:
                website_url = _safe_external_profile_url(
                    google_place.get("website_uri")
                )
                contact_uses_google = contact_uses_google or bool(website_url)
            contact_uses_google = contact_uses_google or bool(contact_google_maps_url)

    profile_contact = None
    if address or phone or website_url or contact_google_maps_url:
        profile_contact = {
            "address": address,
            "phone": phone,
            "website_url": website_url,
            "google_maps_url": contact_google_maps_url,
            "uses_google_maps": contact_uses_google,
        }

    google_review_summary = None
    if needs_google_reviews and google_place:
        rating = google_place.get("rating")
        user_rating_count = google_place.get("user_rating_count")
        if isinstance(rating, (int, float)) and not isinstance(rating, bool):
            google_review_summary = {
                "rating": f"{float(rating):.1f}",
                "user_rating_count": user_rating_count
                if isinstance(user_rating_count, int)
                and not isinstance(user_rating_count, bool)
                else None,
                "google_maps_url": google_maps_url,
            }

    return {
        "profile_contact": profile_contact,
        "google_review_summary": google_review_summary,
    }


def _shadow_profile_placeholders(
    *,
    calendar: InternalCalendar,
    captain_avatar_url: str | None,
    boat_media: list[CharterProfileMedia],
    gallery_media: list[CharterProfileMedia],
    google_review_summary: dict[str, Any] | None = None,
) -> list[dict[str, str]]:
    placeholders = []

    if not captain_avatar_url:
        placeholders.append(
            {
                "title": "Captain profile photo",
                "body": "A captain portrait or headshot can appear here after the page is claimed.",
            }
        )
    if not calendar.captain_bio:
        placeholders.append(
            {
                "title": "Captain bio",
                "body": "A short captain story helps customers understand who they will fish with.",
            }
        )
    if not boat_media:
        placeholders.append(
            {
                "title": "Boat photos",
                "body": "Photos of the vessel can appear here so customers know what they are booking.",
            }
        )
    if not calendar.boat_specs:
        placeholders.append(
            {
                "title": "Boat specs",
                "body": "Length, capacity, electronics, comfort features, and safety equipment can be listed here.",
            }
        )
    if not gallery_media:
        placeholders.append(
            {
                "title": "Recent catch gallery",
                "body": "Catch photos or trip-gallery images can appear here once the captain adds them.",
            }
        )
    if not calendar.whats_included:
        placeholders.append(
            {
                "title": "What's included",
                "body": "Licenses, rods, bait, tackle, cleaning help, and crew details can be called out here.",
            }
        )
    if not calendar.what_to_bring:
        placeholders.append(
            {
                "title": "What to bring",
                "body": "This can set expectations for food, drinks, sunscreen, shoes, and weather layers.",
            }
        )
    if not calendar.cancellation_weather_policy:
        placeholders.append(
            {
                "title": "Cancellation and weather policy",
                "body": "A weather and reschedule policy can reduce back-and-forth before booking.",
            }
        )
    if (
        not calendar.testimonials
        and not calendar.reviews_url
        and not google_review_summary
    ):
        placeholders.append(
            {
                "title": "Reviews or testimonials",
                "body": "Testimonials or a reviews link can appear here when the captain is ready to share them.",
            }
        )

    return placeholders


@feature_flag_check("enable-charter-mode")
def public_charter_calendar(request: HttpRequest, public_slug: str) -> HttpResponse:
    """
    Public view for a charter calendar - accessible without authentication
    """
    calendar = get_object_or_404(_direct_charter_calendars(), public_slug=public_slug)

    # Get upcoming charter events for this calendar (annotate seat aggregates
    # up-front so the loop below does not issue per-event queries).
    events = annotate_event_availability(
        Event.objects.filter(
            internal_calendar=calendar,
            is_charter_event=True,
            start_time__gte=timezone.now(),
        )
    ).order_by("start_time")

    # Calculate available seats for each event
    events_with_availability = []
    for event in events:
        availability = _event_availability(event)
        events_with_availability.append(
            {
                "event": event,
                "available_seats": availability["available"],
                "pending_seats": availability["pending"],
                "is_fully_booked": availability["is_fully_booked"],
            }
        )

    boat_media = list(
        CharterProfileMedia.objects.filter(
            calendar=calendar, is_active=True, media_type="BOAT"
        )
    )
    gallery_media = list(
        CharterProfileMedia.objects.filter(calendar=calendar, is_active=True).exclude(
            media_type="BOAT"
        )
    )
    captain_avatar_url = resolve_user_avatar(
        calendar.user, request_host=request.get_host(), cache={}
    )
    is_shadow_page = calendar.publication_status == "SHADOW"
    profile_fallbacks = _charter_public_profile_fallbacks(
        calendar=calendar,
        is_shadow_page=is_shadow_page,
    )
    shadow_profile_placeholders = (
        _shadow_profile_placeholders(
            calendar=calendar,
            captain_avatar_url=captain_avatar_url,
            boat_media=boat_media,
            gallery_media=gallery_media,
            google_review_summary=profile_fallbacks["google_review_summary"],
        )
        if is_shadow_page
        else []
    )

    context = {
        "calendar": calendar,
        "events_with_availability": events_with_availability,
        "captain": calendar.user,
        "captain_display_name": _captain_display_name(calendar),
        "captain_avatar_url": captain_avatar_url,
        "boat_media": boat_media,
        "gallery_media": gallery_media,
        "profile_contact": profile_fallbacks["profile_contact"],
        "google_review_summary": profile_fallbacks["google_review_summary"],
        "is_shadow_page": is_shadow_page,
        "shadow_profile_placeholders": shadow_profile_placeholders,
    }

    response = render(request, "charters/public_calendar.html", context)
    if calendar.publication_status == "SHADOW":
        response.headers["X-Robots-Tag"] = "noindex, nofollow"
    return response


@feature_flag_check("enable-charter-mode")
def all_charter_calendars(request: HttpRequest) -> HttpResponse:
    """
    Public view listing all available charter calendars
    """
    calendars = _public_charter_calendars()

    calendars_with_info = []
    for calendar in calendars:
        # Get next upcoming event for each calendar (annotated with seat
        # aggregates so we avoid per-event availability queries below).
        next_event = _next_event_for_calendar(calendar)

        next_event_available_seats = None
        next_event_pending_seats = 0
        if next_event:
            availability = _event_availability(next_event)
            next_event_available_seats = availability["available"]
            next_event_pending_seats = availability["pending"]

        calendars_with_info.append(
            {
                "calendar": calendar,
                "captain": calendar.user,
                "captain_display_name": _captain_display_name(calendar),
                "next_event": next_event,
                "next_event_available_seats": next_event_available_seats,
                "next_event_pending_seats": next_event_pending_seats,
            }
        )

    context = {
        "calendars_with_info": calendars_with_info,
    }

    return render(request, "charters/calendar_list.html", context)


@feature_flag_check("enable-charter-mode")
def captain_invite(request: HttpRequest, token: str) -> HttpResponse:
    """
    Captain invite landing page (new signups only).

    Stores the invite token in the session and routes the recipient to the
    correct entry point so provisioning completes after authentication:

    - New users (no ClanCal account): directed to /accounts/signup/. The signup
      form (CustomSignupForm.save) consumes the session token and provisions the
      CAPTAIN role + draft calendar.
    - Existing users: directed to /accounts/login/ with a ?next= pointing at the
      captain setup page. The session token is consumed by
      ``provision_charter_captain_from_invite`` on login. (Previously this case
      dead-ended on an HTTP 400 page.)
    """
    invite = CharterCaptainInvite.objects.filter(token=token).first()
    if not invite:
        return render(request, "charters/captain_invite_invalid.html", status=404)

    now = timezone.now()
    if invite.status != "PENDING":
        return render(request, "charters/captain_invite_invalid.html", status=410)

    if invite.expires_at <= now:
        invite.status = "EXPIRED"
        invite.save(update_fields=["status"])
        return render(request, "charters/captain_invite_invalid.html", status=410)

    next_url = reverse("charter:captain_calendar_setup")

    # Existing accounts: store the token and send the user through login so the
    # post-login provisioning hook can claim the invite. The service layer
    # (provision_charter_captain_from_invite) handles provisioning for both new
    # and existing users; it just needs to be invoked after authentication.
    if User.objects.filter(email__iexact=invite.email).exists():
        store_invite_token_in_session(request, invite.token)
        login_url = reverse("account_login")
        return redirect(f"{login_url}?next={next_url}")

    # New signups: store the token and direct the user to signup.
    store_invite_token_in_session(request, invite.token)

    signup_url = reverse("account_signup")
    context = {
        "invite": invite,
        "signup_url": f"{signup_url}?next={next_url}",
    }
    return render(request, "charters/captain_invite_landing.html", context)


def _make_unique_public_slug(*, base_slug: str, exclude_calendar_id: str) -> str:
    """
    Make a unique InternalCalendar.public_slug by appending a numeric suffix if needed.
    """
    slug = base_slug[:100]
    counter = 2
    while (
        slug
        and InternalCalendar.objects.filter(public_slug=slug)
        .exclude(id=exclude_calendar_id)
        .exists()
    ):
        suffix = f"-{counter}"
        slug = f"{base_slug[: 100 - len(suffix)]}{suffix}"
        counter += 1
    return slug


@login_required
@feature_flag_check("enable-charter-mode")
def captain_calendar_setup(request: HttpRequest) -> HttpResponse:
    """
    Captain-only setup page for creating/publishing their charter calendar.
    """
    user = _get_request_user(request)

    if not FamilyMembership.objects.filter(user=user, role="CAPTAIN").exists():
        security_log_access_denied(
            user_id=user.id,
            action="charter.captain.calendar_setup",
            object_type="internal_calendar",
            object_id=None,
            reason="user_not_captain",
        )
        return render(request, "charters/access_denied.html", status=403)

    calendar = (
        InternalCalendar.objects.filter(user=user, type="CHARTER")
        .order_by("created_at")
        .first()
    )
    if not calendar:
        full_name = user.get_full_name() or user.username
        calendar = InternalCalendar.objects.create(
            user=user,
            name=f"{full_name}'s Charters",
            description="",
            type="CHARTER",
            is_active=True,
            is_public=False,
        )
        add_calendar_associated_user_safely(
            calendar, user, context="captain calendar setup"
        )

    if request.method == "POST":
        name = (request.POST.get("name") or "").strip()
        description = (request.POST.get("description") or "").strip()
        boat_name = (request.POST.get("boat_name") or "").strip()
        charter_description = (request.POST.get("charter_description") or "").strip()
        captain_display_name = (request.POST.get("captain_display_name") or "").strip()
        captain_bio = (request.POST.get("captain_bio") or "").strip()
        boat_specs = (request.POST.get("boat_specs") or "").strip()
        whats_included = (request.POST.get("whats_included") or "").strip()
        what_to_bring = (request.POST.get("what_to_bring") or "").strip()
        cancellation_weather_policy = (
            request.POST.get("cancellation_weather_policy") or ""
        ).strip()
        business_address = (request.POST.get("business_address") or "").strip()
        business_phone = (request.POST.get("business_phone") or "").strip()
        business_website_url = (request.POST.get("business_website_url") or "").strip()
        google_place_id = (request.POST.get("google_place_id") or "").strip()
        use_google_contact_info = request.POST.get("use_google_contact_info") == "on"
        use_google_reviews = request.POST.get("use_google_reviews") == "on"
        reviews_url = (request.POST.get("reviews_url") or "").strip()
        testimonials = (request.POST.get("testimonials") or "").strip()
        slug_raw = (request.POST.get("public_slug") or "").strip()
        publication_status = request.POST.get("publication_status") or (
            "PUBLIC" if request.POST.get("is_public") == "on" else "PRIVATE"
        )

        boat_capacity = None
        boat_capacity_raw = (request.POST.get("boat_capacity") or "").strip()
        errors = []

        if not name:
            errors.append("Calendar name is required.")

        if publication_status not in {"PRIVATE", "SHADOW", "PUBLIC"}:
            errors.append("Invalid publication status.")

        # reviews_url is rendered as an <a href> on the public page; reject any
        # scheme other than http/https to prevent javascript:/data: XSS.
        safe_reviews_url = _validate_safe_url(reviews_url)
        if safe_reviews_url is None:
            errors.append("Reviews URL must start with http:// or https://")
        else:
            reviews_url = safe_reviews_url

        safe_business_website_url = _validate_safe_url(business_website_url)
        if safe_business_website_url is None:
            errors.append("Website URL must start with http:// or https://")
        else:
            business_website_url = safe_business_website_url

        if boat_capacity_raw:
            try:
                boat_capacity_val = int(boat_capacity_raw)
                if boat_capacity_val <= 0:
                    raise ValueError
                boat_capacity = boat_capacity_val
            except ValueError:
                errors.append("Boat capacity must be a positive number.")

        slug_value = slugify(slug_raw) if slug_raw else ""
        if publication_status in {"PUBLIC", "SHADOW"} and not slug_value:
            slug_value = slugify(name) if name else ""

        if publication_status in {"PUBLIC", "SHADOW"} and not slug_value:
            errors.append("A public URL is required to publish your charter page.")

        if slug_value:
            slug_value = _make_unique_public_slug(
                base_slug=slug_value, exclude_calendar_id=str(calendar.id)
            )

        if (
            slug_value
            and InternalCalendar.objects.filter(public_slug=slug_value)
            .exclude(id=calendar.id)
            .exists()
        ):
            errors.append("That public URL is already taken. Please choose another.")

        if errors:
            context = {
                "calendar": calendar,
                "errors": errors,
                "form_data": request.POST,
                "publication_status_choices": InternalCalendar.PUBLICATION_STATUS_CHOICES,
                "use_google_contact_info_checked": use_google_contact_info,
                "use_google_reviews_checked": use_google_reviews,
            }
            return render(request, "charters/captain_calendar_setup.html", context)

        calendar.name = name
        calendar.description = description
        calendar.boat_name = boat_name
        calendar.boat_capacity = boat_capacity
        calendar.charter_description = charter_description
        calendar.captain_display_name = captain_display_name
        calendar.captain_bio = captain_bio
        calendar.boat_specs = boat_specs
        calendar.whats_included = whats_included
        calendar.what_to_bring = what_to_bring
        calendar.cancellation_weather_policy = cancellation_weather_policy
        calendar.business_address = business_address
        calendar.business_phone = business_phone
        calendar.business_website_url = business_website_url
        calendar.google_place_id = google_place_id
        calendar.use_google_contact_info = use_google_contact_info
        calendar.use_google_reviews = use_google_reviews
        calendar.reviews_url = reviews_url
        calendar.testimonials = testimonials
        calendar.public_slug = slug_value or None
        # publication_status is the single source of truth; InternalCalendar.save()
        # derives is_public (PUBLIC => True, else False), so we no longer set it here.
        calendar.publication_status = publication_status
        calendar.save()

        messages.success(request, "Your charter calendar has been updated.")
        return redirect("charter:captain_dashboard")

    context = {
        "calendar": calendar,
        "publication_status_choices": InternalCalendar.PUBLICATION_STATUS_CHOICES,
        "use_google_contact_info_checked": calendar.use_google_contact_info,
        "use_google_reviews_checked": calendar.use_google_reviews,
    }
    return render(request, "charters/captain_calendar_setup.html", context)


@login_required
@feature_flag_check("enable-charter-mode")
def booking_request_form(request: HttpRequest, event_id: str) -> HttpResponse:
    """
    Form for authenticated users to request a charter booking
    """
    event = get_object_or_404(
        Event, id=event_id, is_charter_event=True, start_time__gte=timezone.now()
    )

    # Check for existing booking or pending request
    existing_request = CharterBookingRequest.objects.filter(
        event=event,
        requested_by=_get_request_user(request),
        status__in=["PENDING", "APPROVED"],
    ).first()
    existing_booking = CharterBooking.objects.filter(
        event=event, user=_get_request_user(request), status="CONFIRMED"
    ).first()

    # Check seat availability
    confirmed_bookings = (
        CharterBooking.objects.filter(event=event, status="CONFIRMED").aggregate(
            total_seats=models.Sum("number_of_seats")
        )["total_seats"]
        or 0
    )

    pending_seats = (
        CharterBookingRequest.objects.filter(event=event, status="PENDING").aggregate(
            total=models.Sum("requested_seats")
        )["total"]
        or 0
    )

    available_seats = (event.available_seats or 0) - confirmed_bookings

    if request.method == "POST":
        # Block duplicate submissions
        if existing_booking or existing_request:
            calendar = event.internal_calendar
            context = {
                "event": event,
                "available_seats": available_seats,
                "calendar": calendar,
                "captain": calendar.user if calendar else None,
                "existing_booking": existing_booking,
                "existing_request": existing_request,
                "error": "You already have an active booking or pending request for this trip.",
            }
            return render(request, "charters/booking_form.html", context)

        try:
            requested_seats = int(request.POST.get("requested_seats", 1))
        except (ValueError, TypeError):
            context = {
                "event": event,
                "available_seats": available_seats,
                "error": "Requested seats must be a number.",
            }
            return render(request, "charters/booking_form.html", context)

        contact_name = request.POST.get("contact_name", "")
        contact_email = request.POST.get("contact_email", "")
        contact_phone = request.POST.get("contact_phone", "")
        special_requests = request.POST.get("special_requests", "")
        try:
            intake_data = _charter_intake_data(request.POST)
        except ValueError:
            context = {
                "event": event,
                "available_seats": available_seats,
                "calendar": event.internal_calendar,
                "captain": event.internal_calendar.user
                if event.internal_calendar
                else None,
                "error": "Passenger counts must be zero or greater.",
                "experience_level_choices": EXPERIENCE_LEVEL_CHOICES,
                "contact_preference_choices": CONTACT_PREFERENCE_CHOICES,
            }
            return render(request, "charters/booking_form.html", context)

        if requested_seats > available_seats:
            context = {
                "event": event,
                "available_seats": available_seats,
                "error": f"Only {available_seats} seats available",
            }
            return render(request, "charters/booking_form.html", context)

        # Create booking request
        booking_request = CharterBookingRequest.objects.create(
            event=event,
            requested_by=_get_request_user(request),
            requested_seats=requested_seats,
            contact_name=contact_name,
            contact_email=contact_email,
            contact_phone=contact_phone,
            special_requests=special_requests,
            **intake_data,
        )

        # Queue notification after transaction commits
        booking_request_id = str(booking_request.id)
        transaction.on_commit(
            lambda: send_charter_booking_request_notification.delay(booking_request_id)
        )

        return redirect(
            "charter:booking_success", booking_request_id=booking_request.id
        )

    calendar = event.internal_calendar
    context = {
        "event": event,
        "available_seats": available_seats,
        "pending_seats": pending_seats,
        "calendar": calendar,
        "captain": calendar.user if calendar else None,
        "existing_booking": existing_booking,
        "existing_request": existing_request,
        "experience_level_choices": EXPERIENCE_LEVEL_CHOICES,
        "contact_preference_choices": CONTACT_PREFERENCE_CHOICES,
    }

    return render(request, "charters/booking_form.html", context)


@login_required
@feature_flag_check("enable-charter-mode")
def custom_inquiry_form(request: HttpRequest, public_slug: str) -> HttpResponse:
    """
    Form for authenticated users to request a custom charter date or trip.
    """
    calendar = get_object_or_404(_direct_charter_calendars(), public_slug=public_slug)

    if request.method == "POST":
        errors = []
        try:
            requested_seats = _parse_required_positive_int(
                request.POST.get("requested_seats")
            )
            preferred_start_date = _parse_optional_date(
                request.POST.get("preferred_start_date")
            )
            preferred_end_date = _parse_optional_date(
                request.POST.get("preferred_end_date")
            )
            intake_data = _charter_intake_data(request.POST)
        except (TypeError, ValueError) as exc:
            # Surface the specific field error instead of swallowing it, and
            # leave requested_seats at 0 so the explicit guard below blocks the
            # inquiry from being created with zero seats.
            errors.append(f"Please check passenger counts and date fields: {exc}")
            requested_seats = 0
            preferred_start_date = None
            preferred_end_date = None
            intake_data = {}

        if (
            preferred_start_date
            and preferred_end_date
            and preferred_start_date > preferred_end_date
        ):
            errors.append("Preferred end date must be on or after the start date.")

        contact_name = (request.POST.get("contact_name") or "").strip()
        contact_phone = (request.POST.get("contact_phone") or "").strip()
        # Security: lock the stored contact_email to the authenticated user's
        # email so an authenticated user cannot spoof someone else's address on
        # the inquiry. contact_name / contact_phone remain free-form from POST.
        contact_email = (_get_request_user(request).email or "").strip()
        if not contact_name:
            errors.append("Contact name is required.")
        if not contact_email:
            errors.append("Email address is required.")
        if not contact_phone:
            errors.append("Phone number is required.")

        # Explicit guard: never create an inquiry with zero (or fewer) seats,
        # even if the parse above failed and defaulted requested_seats to 0.
        if not errors and requested_seats <= 0:
            errors.append("At least one passenger seat is required.")

        if errors:
            context = {
                "calendar": calendar,
                "captain_display_name": _captain_display_name(calendar),
                "errors": errors,
                "form_data": request.POST,
                "experience_level_choices": EXPERIENCE_LEVEL_CHOICES,
                "contact_preference_choices": CONTACT_PREFERENCE_CHOICES,
            }
            return render(request, "charters/custom_inquiry_form.html", context)

        inquiry_fields = {
            "calendar": calendar,
            "requested_by": _get_request_user(request),
            "requested_seats": requested_seats,
            "adult_count": intake_data.get("adult_count"),
            "child_count": intake_data.get("child_count"),
            "contact_name": contact_name,
            "contact_email": contact_email,
            "contact_phone": contact_phone,
            "preferred_start_date": preferred_start_date,
            "preferred_end_date": preferred_end_date,
            "preferred_time_of_day": (
                request.POST.get("preferred_time_of_day") or ""
            ).strip(),
            "date_flexibility": (request.POST.get("date_flexibility") or "").strip(),
            "experience_level": intake_data.get("experience_level", ""),
            "target_species": intake_data.get("target_species", ""),
            "contact_preference": intake_data.get("contact_preference", ""),
            "accessibility_notes": intake_data.get("accessibility_notes", ""),
            "has_fished_with_us_before": intake_data.get("has_fished_with_us_before"),
            "special_requests": (request.POST.get("special_requests") or "").strip(),
        }
        recent_duplicate = (
            CharterInquiry.objects.filter(
                **inquiry_fields,
                status="NEW",
                created_at__gte=timezone.now() - timedelta(minutes=2),
            )
            .order_by("created_at")
            .first()
        )
        if recent_duplicate:
            return redirect("charter:inquiry_success", inquiry_id=recent_duplicate.id)

        inquiry = CharterInquiry.objects.create(
            **inquiry_fields,
        )

        inquiry_id = str(inquiry.id)
        transaction.on_commit(
            lambda: send_charter_inquiry_notification.delay(inquiry_id)
        )
        return redirect("charter:inquiry_success", inquiry_id=inquiry.id)

    context = {
        "calendar": calendar,
        "captain_display_name": _captain_display_name(calendar),
        "experience_level_choices": EXPERIENCE_LEVEL_CHOICES,
        "contact_preference_choices": CONTACT_PREFERENCE_CHOICES,
    }
    return render(request, "charters/custom_inquiry_form.html", context)


