@login_required
@feature_flag_check("enable-charter-mode")
def my_bookings(request: HttpRequest) -> HttpResponse:
    """
    Customer view to see their booking requests and confirmed bookings
    """
    now = timezone.now()

    # All booking requests by this user
    booking_requests = (
        CharterBookingRequest.objects.filter(requested_by=_get_request_user(request))
        .select_related("event", "event__internal_calendar")
        .order_by("-created_at")
    )

    # All confirmed bookings by this user
    confirmed_bookings = (
        CharterBooking.objects.filter(user=_get_request_user(request))
        .select_related("event", "event__internal_calendar", "booking_request")
        .order_by("-created_at")
    )

    # Categorize
    upcoming_bookings = confirmed_bookings.filter(
        status="CONFIRMED", event__start_time__gte=now
    )
    pending_requests = booking_requests.filter(status="PENDING")
    past_bookings = confirmed_bookings.filter(
        models.Q(event__start_time__lt=now) | ~models.Q(status="CONFIRMED")
    )
    past_requests = booking_requests.filter(status__in=["REJECTED", "CANCELLED"])

    context = {
        "upcoming_bookings": upcoming_bookings,
        "pending_requests": pending_requests,
        "past_bookings": past_bookings,
        "past_requests": past_requests,
    }

    return render(request, "charters/my_bookings.html", context)


@login_required
@feature_flag_check("enable-charter-mode")
def captain_dashboard(request: HttpRequest) -> HttpResponse:
    """
    Dashboard for captains to manage their charter calendars and bookings
    """
    # Check if user is a captain
    if not FamilyMembership.objects.filter(
        user=_get_request_user(request), role="CAPTAIN"
    ).exists():
        return render(request, "charters/access_denied.html", status=403)

    # Get captain's charter calendars
    charter_calendars = InternalCalendar.objects.filter(
        user=_get_request_user(request), type="CHARTER", is_active=True
    )

    # Get pending booking requests. The template accesses request.event.title
    # and renders the owning calendar, so select_related avoids per-row queries.
    # Materialize to a list so the badge count and the table loop share a single
    # query (the template uses pending_requests_count for the badge).
    pending_requests = list(
        CharterBookingRequest.objects.filter(
            event__internal_calendar__in=charter_calendars, status="PENDING"
        )
        .select_related("event", "event__internal_calendar", "requested_by")
        .order_by("-created_at")
    )

    custom_inquiries = (
        CharterInquiry.objects.filter(
            calendar__in=charter_calendars,
            status__in=["NEW", "CONTACTED", "AWAITING_REPLY"],
        )
        .select_related("calendar", "event")
        .order_by("-created_at")
    )

    # Get recent bookings
    recent_bookings = (
        CharterBooking.objects.filter(
            event__internal_calendar__in=charter_calendars, status="CONFIRMED"
        )
        .select_related("event", "event__internal_calendar")
        .order_by("-created_at")[:10]
    )

    # Get upcoming events with availability info (annotate seat aggregates once
    # so the loop below does not issue per-event queries).
    upcoming_events_qs = annotate_event_availability(
        Event.objects.filter(
            internal_calendar__in=charter_calendars,
            is_charter_event=True,
            start_time__gte=timezone.now(),
        )
    ).order_by("start_time")[:10]

    upcoming_events = []
    for event in upcoming_events_qs:
        availability = _event_availability(event)
        upcoming_events.append(
            {
                "event": event,
                "confirmed_seats": availability["confirmed"],
                "pending_seats": availability["pending"],
                "available_seats": availability["available"],
                "total_seats": availability["total_seats"],
            }
        )

    context = {
        "charter_calendars": charter_calendars,
        "pending_requests": pending_requests,
        "pending_requests_count": len(pending_requests),
        "custom_inquiries": custom_inquiries,
        "recent_bookings": recent_bookings,
        "upcoming_events": upcoming_events,
        "inquiry_status_choices": CharterInquiry.STATUS_CHOICES,
        "trip_action_choices": CharterTripStatusUpdate.ACTION_CHOICES,
        "trip_reason_choices": CharterTripStatusUpdate.REASON_CHOICES,
    }

    return render(request, "charters/captain_dashboard.html", context)


@login_required
@feature_flag_check("enable-charter-mode")
@require_http_methods(["POST"])
def approve_booking(request: HttpRequest, booking_request_id: str) -> HttpResponse:
    """
    Captain approves a booking request
    """
    booking_request = get_object_or_404(
        CharterBookingRequest, id=booking_request_id, status="PENDING"
    )

    calendar = booking_request.event.internal_calendar
    if not _is_captain_of_calendar(_get_request_user(request), calendar):
        logger.warning(
            "Unauthorized approve attempt by user %s for booking_request %s",
            _get_request_user(request).id,
            booking_request_id,
        )
        return render(request, "charters/access_denied.html", status=403)

    try:
        booking = booking_request.approve(_get_request_user(request))

        # Queue confirmation email after transaction commits
        booking_id = str(booking.id)
        transaction.on_commit(
            lambda: send_charter_booking_confirmation.delay(booking_id)
        )

        return redirect("charter:captain_dashboard")
    except ValueError:
        logger.warning(
            "Cannot approve booking_request %s: not enough seats",
            booking_request_id,
        )
        messages.error(
            request,
            "Cannot approve: not enough seats available for this event.",
        )
        return redirect("charter:captain_dashboard")


@login_required
@feature_flag_check("enable-charter-mode")
@require_http_methods(["POST"])
def reject_booking(request: HttpRequest, booking_request_id: str) -> HttpResponse:
    """
    Captain rejects a booking request
    """
    booking_request = get_object_or_404(
        CharterBookingRequest, id=booking_request_id, status="PENDING"
    )

    calendar = booking_request.event.internal_calendar
    if not _is_captain_of_calendar(_get_request_user(request), calendar):
        logger.warning(
            "Unauthorized reject attempt by user %s for booking_request %s",
            _get_request_user(request).id,
            booking_request_id,
        )
        return render(request, "charters/access_denied.html", status=403)

    reason = request.POST.get("rejection_reason", "")
    try:
        booking_request.reject(_get_request_user(request), reason)
    except Exception:
        logger.exception(
            "Failed to reject booking_request %s by user %s",
            booking_request_id,
            _get_request_user(request).id,
        )
        messages.error(
            request,
            "Unable to reject this booking request. Please try again.",
        )
        return redirect("charter:captain_dashboard")

    # Queue rejection email after transaction commits
    br_id = str(booking_request.id)
    transaction.on_commit(lambda: send_charter_booking_rejection.delay(br_id))

    return redirect("charter:captain_dashboard")


