    event = get_object_or_404(Event, id=event_id, is_charter_event=True)
    calendar = event.internal_calendar
    if not _is_captain_of_calendar(_get_request_user(request), calendar):
        return render(request, "charters/access_denied.html", status=403)

    action = (request.POST.get("action") or "").strip()
    reason = (request.POST.get("reason") or "").strip()
    if action not in dict(CharterTripStatusUpdate.ACTION_CHOICES):
        messages.error(request, "Invalid trip status action.")
        return redirect("charter:captain_dashboard")
    if reason and reason not in dict(CharterTripStatusUpdate.REASON_CHOICES):
        messages.error(request, "Invalid trip status reason.")
        return redirect("charter:captain_dashboard")

    try:
        proposed_start_time = _parse_local_datetime(
            request.POST.get("proposed_start_time")
        )
        proposed_end_time = _parse_local_datetime(request.POST.get("proposed_end_time"))
    except ValueError:
        messages.error(request, "Invalid proposed reschedule time.")
        return redirect("charter:captain_dashboard")

    if action == "RESCHEDULE_PROPOSED":
        if not proposed_start_time or not proposed_end_time:
            messages.error(request, "Proposed start and end times are required.")
            return redirect("charter:captain_dashboard")
        if proposed_start_time >= proposed_end_time:
            messages.error(request, "Proposed end time must be after start time.")
            return redirect("charter:captain_dashboard")

    captain_message = (request.POST.get("captain_message") or "").strip()
    with transaction.atomic():
        update = CharterTripStatusUpdate.objects.create(
            event=event,
            action=action,
            reason=reason,
            proposed_start_time=proposed_start_time,
            proposed_end_time=proposed_end_time,
            captain_message=captain_message,
            actor=_get_request_user(request),
        )
        event.charter_trip_status = action
        event.save(update_fields=["charter_trip_status"])

        update_id = str(update.id)
        transaction.on_commit(lambda: send_charter_trip_status_update.delay(update_id))

    messages.success(request, "Trip status updated.")
    return redirect("charter:captain_dashboard")


@login_required
@feature_flag_check("enable-charter-mode")
def captain_monthly_calendar(request: HttpRequest) -> HttpResponse:
    """
    Monthly calendar view for charter captains to see their availability and bookings
    """
    # Check if user is a captain
    if not FamilyMembership.objects.filter(
        user=_get_request_user(request), role="CAPTAIN"
    ).exists():
        return render(request, "charters/access_denied.html", status=403)

    # Get captain's charter calendars
    charter_calendars = InternalCalendar.objects.filter(
        user=_get_request_user(request), type="CHARTER", is_active=True
    )

    if not charter_calendars.exists():
        empty_context = {
            "message": "No charter calendars found. Please set up your charter calendar first."
        }
        return render(request, "charters/captain_calendar.html", empty_context)

    # Get the current date or the requested date.
    now_for_defaults = timezone.now()
    year_str = request.GET.get("year")
    month_str = request.GET.get("month")
    year = int(year_str) if year_str and year_str.isdigit() else now_for_defaults.year
    month = (
        int(month_str) if month_str and month_str.isdigit() else now_for_defaults.month
    )

    # Bound the values so out-of-range input (e.g. month=0/13, which raises
    # calendar.IllegalMonthError) cannot produce a 500. Fall back to the current
    # month/year when the request is out of range.
    if not 1 <= month <= 12:
        month = now_for_defaults.month
    if not 2000 <= year <= 2100:
        year = now_for_defaults.year

    # Get current date and time for highlighting today
    now = timezone.now()

    # Create calendar for the specified month
    cal_month = cal_module.monthcalendar(year, month)
    month_name = cal_module.month_name[month]

    # Calculate previous and next month/year for navigation
    current_date = datetime(year, month, 1)
    prev_date = current_date - timedelta(days=1)
    next_date = (current_date + timedelta(days=32)).replace(day=1)
    prev_month, prev_year = prev_date.month, prev_date.year
    next_month, next_year = next_date.month, next_date.year

    # Get start and end dates for the month
    first_day = datetime(year, month, 1, tzinfo=timezone.get_current_timezone())
    if month == 12:
        last_day = datetime(
            year + 1, 1, 1, tzinfo=timezone.get_current_timezone()
        ) - timedelta(days=1)
    else:
        last_day = datetime(
            year, month + 1, 1, tzinfo=timezone.get_current_timezone()
        ) - timedelta(days=1)
    month_end_datetime = last_day.replace(
        hour=23, minute=59, second=59, microsecond=999999
    )

    # Get charter events for the month (annotate seat aggregates once so the
    # loop below does not issue per-event queries).
    charter_events = (
        annotate_event_availability(
            Event.objects.filter(
                internal_calendar__in=charter_calendars,
                is_charter_event=True,
                start_time__gte=first_day,
                start_time__lte=month_end_datetime,
            )
        )
        .select_related("internal_calendar")
        .order_by("start_time")
    )

    # Calculate availability for each event
    events_with_availability = []
    for event in charter_events:
        availability = _event_availability(event)
        events_with_availability.append(
            {
                "event": event,
                "confirmed_bookings": availability["confirmed"],
                "pending_bookings": availability["pending"],
                "available_seats": availability["available"],
                "is_fully_booked": availability["is_fully_booked"],
                "booking_percentage": availability["booking_percentage"],
            }
        )

    # Organize events by day
    events_by_day: dict[int, list[dict[str, Any]]] = {}
    for event_data in events_with_availability:
        current_event: Event = event_data["event"]
        event_day = current_event.start_time.astimezone(
            timezone.get_current_timezone()
        ).date()

        if event_day.year == year and event_day.month == month:
            day_num = event_day.day
            if day_num not in events_by_day:
                events_by_day[day_num] = []
            events_by_day[day_num].append(event_data)

    # Get pending booking requests for the month
    pending_requests = (
        CharterBookingRequest.objects.filter(
            event__internal_calendar__in=charter_calendars,
            status="PENDING",
            event__start_time__gte=first_day,
            event__start_time__lte=month_end_datetime,
        )
        .select_related("event", "requested_by")
        .order_by("created_at")
    )

    context: dict[str, Any] = {
        "cal_month": cal_month,
        "month_name": month_name,
        "year": year,
        "month": month,
        "prev_month": prev_month,
        "prev_year": prev_year,
        "next_month": next_month,
        "next_year": next_year,
        "events_by_day": events_by_day,
        "events_with_availability": events_with_availability,
        "now": now,
        "charter_calendars": charter_calendars,
        "pending_requests": pending_requests,
        "trip_action_choices": CharterTripStatusUpdate.ACTION_CHOICES,
        "trip_reason_choices": CharterTripStatusUpdate.REASON_CHOICES,
    }

    return render(request, "charters/captain_calendar.html", context)


@login_required
@feature_flag_check("enable-charter-mode")
def create_charter_event(request: HttpRequest) -> HttpResponse:
    """
    Captain-only view to create a new charter event with pre-filled defaults.
    """
    user = _get_request_user(request)

    # Check if user is a captain
    if not FamilyMembership.objects.filter(user=user, role="CAPTAIN").exists():
        return render(request, "charters/access_denied.html", status=403)

    # Get captain's charter calendars
    charter_calendars = InternalCalendar.objects.filter(
        user=user, type="CHARTER", is_active=True
    )

    if not charter_calendars.exists():
        messages.warning(request, "Please set up your charter calendar first.")
        return redirect("charter:captain_calendar_setup")

    if request.method == "POST":
        title = request.POST.get("title", "").strip()
        description = request.POST.get("description", "").strip()
        start_time_str = request.POST.get("start_time", "")
        end_time_str = request.POST.get("end_time", "")
        location = request.POST.get("location", "").strip()
        seats_str = request.POST.get("available_seats")
        price_raw = (request.POST.get("price_per_seat") or "").strip()
        charter_type = request.POST.get("charter_type", "")
        calendar_id = request.POST.get("calendar")

        errors = []
        if not title:
            errors.append("Title is required.")
        if not start_time_str:
            errors.append("Start time is required.")
        if not end_time_str:
            errors.append("End time is required.")
        if not seats_str:
            errors.append("Available seats is required.")
        if not calendar_id:
            errors.append("Calendar is required.")

        # Validate seats is a number
        available_seats_val = None
        if seats_str:
            try:
                available_seats_val = int(seats_str)
            except (ValueError, TypeError):
                errors.append("Available seats must be a number.")

        price_per_seat = None
        if price_raw:
            try:
                price_per_seat_val = Decimal(price_raw)
                if price_per_seat_val < 0:
                    raise ValueError
                price_per_seat = price_per_seat_val
            except (InvalidOperation, ValueError):
                errors.append("Price per seat must be a valid non-negative amount.")

        # Validate charter_type against the model's allowed choices. An empty
        # value is permitted (the field is blank=True); any other value must be
        # one of the defined choices.
        valid_charter_types = {
            choice[0]
            for choice in (Event._meta.get_field("charter_type").choices or [])
        }
        if charter_type and charter_type not in valid_charter_types:
            errors.append("Invalid charter type selected.")

        if errors:
            context = {
                "charter_calendars": charter_calendars,
                "errors": errors,
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        # Parse datetimes using the timezone activated by TimezoneMiddleware.
        # _parse_local_datetime uses timezone.make_aware (DST-safe) instead of a
        # naive datetime.replace(tzinfo=...) which mishandles DST transitions.
        try:
            start_time = _parse_local_datetime(start_time_str)
            end_time = _parse_local_datetime(end_time_str)
        except (ValueError, TypeError):
            context = {
                "charter_calendars": charter_calendars,
                "errors": ["Invalid date/time format."],
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        if not start_time or not end_time:
            context = {
                "charter_calendars": charter_calendars,
                "errors": ["Invalid date/time format."],
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        if start_time >= end_time:
            context = {
                "charter_calendars": charter_calendars,
                "errors": ["End time must be after start time."],
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        calendar_uuid: UUID | None = None
        if calendar_id:
            try:
                calendar_uuid = UUID(calendar_id)
            except ValueError:
                calendar_uuid = None

        # Early-return when the calendar id is missing or unparseable. This makes
        # calendar_uuid provably non-None below without a runtime assert.
        if calendar_uuid is None:
            errors.append("Invalid calendar selected.")
            context = {
                "charter_calendars": charter_calendars,
                "errors": errors,
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        try:
            calendar = charter_calendars.get(id=calendar_uuid)
        except InternalCalendar.DoesNotExist:
            context = {
                "charter_calendars": charter_calendars,
                "errors": ["Invalid calendar selected."],
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        # Get captain's family
        membership = FamilyMembership.objects.filter(user=user, role="CAPTAIN").first()

        try:
            with transaction.atomic():
                Event.objects.create(
                    title=title,
                    description=description,
                    start_time=start_time,
                    end_time=end_time,
                    location=location,
                    creator=user,
                    family_group=membership.family if membership else None,
                    visibility="PUBLIC",
                    internal_calendar=calendar,
                    is_charter_event=True,
                    available_seats=available_seats_val,
                    price_per_seat=price_per_seat,
                    charter_type=charter_type,
                )
        except Exception:
            logger.exception("Failed to create charter event for captain %s", user.id)
            context = {
                "charter_calendars": charter_calendars,
                "errors": ["An error occurred creating the event. Please try again."],
                "form_data": request.POST,
            }
            return render(request, "charters/create_charter_event.html", context)

        messages.success(request, "Charter event created successfully.")
        return redirect("charter:captain_dashboard")

    context = {
        "charter_calendars": charter_calendars,
    }
    return render(request, "charters/create_charter_event.html", context)
